# slate: nodes/scoring/clamp
# intent: Clamp a value to inclusive bounds
# contract: Clamp value between lower and upper inclusive
def clamp(value: int, lower: int = 0, upper: int = 100) -> int:
    return max(lower, min(value, upper))


